<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'
import { Bot, Check, CircleAlert, Clock3, Plus, Tags, Trash2, Workflow as WorkflowIcon } from 'lucide-vue-next'
import AppShell from '@/components/AppShell.vue'; import api from '@/api/client'; import ActionCard from '@/volt/ActionCard.vue'; import AlertBanner from '@/components/ui/AlertBanner.vue'; import Button from '@/volt/Button.vue'; import IconButton from '@/volt/IconButton.vue'; import InputText from '@/volt/InputText.vue'; import { useWorkspacesStore } from '@/stores/workspaces'
import EmptyState from '@/components/ui/EmptyState.vue'; import FormField from '@/components/ui/FormField.vue'; import ModalShell from '@/components/ui/ModalShell.vue'; import PageHeader from '@/components/ui/PageHeader.vue'; import Textarea from '@/volt/Textarea.vue'
import FilterDropdown from '@/components/ui/FilterDropdown.vue'; import SearchInput from '@/components/ui/SearchInput.vue'
const { t } = useI18n(); const router = useRouter(); const workspaces = useWorkspacesStore(); const items = ref<any[]>([]); const search = ref(''); const creating = ref(false); const createError = ref(''); const showCreate = ref(false); const type = ref('all'); const status = ref('all'); const newestFirst = ref(true); const pendingDelete = ref<any>(null); const deleting = ref(false); const deleteError = ref(''); const form = ref<{ name: string; description: string; app_type: string; template_id?: string }>({ name: '', description: '', app_type: 'workflow' })
const canEdit = computed(() => ['owner', 'admin', 'editor'].includes(workspaces.active?.role || ''))
const filtered = computed(() => items.value.filter(item => item.name.toLowerCase().includes(search.value.toLowerCase()) && (type.value === 'all' || item.app_type === type.value) && (status.value === 'all' || (status.value === 'published') === Boolean(item.published_version_id))).sort((a, b) => (new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime()) * (newestFirst.value ? 1 : -1)))
const typeOptions = computed(() => ['all','workflow','chat'].map(value => ({ value, label: value === 'all' ? t('studio.all') : t(`studio.${value}`) })))
const statusOptions = computed(() => ['all','published','draft'].map(value => ({ value, label: value === 'all' ? t('studio.allStatuses') : t(`studio.${value}`) })))
async function load() { if (workspaces.activeId) items.value = (await api.get(`/workspaces/${workspaces.activeId}/workflows`)).data }
function selectAppType(value: string) { form.value.app_type = value }
async function create() { creating.value = true; createError.value = ''; try { const { data } = await api.post(`/workspaces/${workspaces.activeId}/workflows`, form.value); showCreate.value = false; router.push(`/w/${workspaces.activeId}/workflows/${data.id}`) } catch (cause: any) { createError.value = cause.response?.data?.detail || String(cause) } finally { creating.value = false } }
function requestDelete(item: any) { pendingDelete.value = item; deleteError.value = '' }
function closeDelete() { if (!deleting.value) pendingDelete.value = null }
async function confirmDelete() { if (!pendingDelete.value || deleting.value) return; deleting.value = true; deleteError.value = ''; try { await api.delete(`/workspaces/${workspaces.activeId}/workflows/${pendingDelete.value.id}`); const deletedId = pendingDelete.value.id; pendingDelete.value = null; items.value = items.value.filter(item => item.id !== deletedId) } catch (cause: any) { deleteError.value = cause.response?.data?.detail || String(cause) } finally { deleting.value = false } }
onMounted(load); watch(() => workspaces.activeId, load)
</script>
<template><AppShell><div class="px-7 py-5"><PageHeader :title="t('studio.title')" :subtitle="t('studio.subtitle')"><template #actions><Button v-if="canEdit" @click="showCreate = true"><Plus :size="16" />{{ t('studio.newApp') }}</Button></template></PageHeader>
<div class="mt-5 flex flex-wrap items-center gap-2"><FilterDropdown v-model="type" :options="typeOptions" /><FilterDropdown v-model="status" :options="statusOptions"><template #icon><Tags :size="14" /></template></FilterDropdown><Button variant="secondary" @click="newestFirst = !newestFirst"><Clock3 :size="14" />{{ newestFirst ? t('studio.recent') : t('studio.oldest') }}</Button><SearchInput v-model="search" class="ml-1 w-64" :placeholder="t('common.search')" /></div>
  <div v-if="filtered.length" class="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4"><div v-for="item in filtered" :key="item.id" class="relative"><ActionCard class="min-h-40 w-full p-4" @click="router.push(`/w/${workspaces.activeId}/workflows/${item.id}`)"><div class="flex gap-3 pr-10"><span class="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[var(--primary-soft)] text-violet-600"><Bot v-if="item.app_type === 'chat'" :size="21" /><WorkflowIcon v-else :size="21" /></span><div class="min-w-0"><h2 class="truncate font-semibold">{{ item.name }}</h2><p class="muted mt-1 line-clamp-2 text-sm">{{ item.description || t('studio.noApps') }}</p></div></div><div class="muted mt-7 flex items-center justify-between border-t border-[var(--border)] pt-3 text-xs"><span>v{{ item.draft_version }} · {{ new Date(item.updated_at).toLocaleDateString() }}</span><span :class="item.published_version_id ? 'text-emerald-600' : ''">{{ item.published_version_id ? t('studio.published') : t('studio.draft') }}</span></div></ActionCard><IconButton v-if="canEdit" class="absolute right-4 top-3 z-10" :label="t('studio.deleteApp', { name: item.name })" tone="danger" surface @click="requestDelete(item)"><Trash2 :size="15" /></IconButton></div></div><EmptyState v-else class="mt-16" :title="t('studio.noResults')"><template #icon><WorkflowIcon :size="42" /></template></EmptyState>
<ModalShell v-model="showCreate" :title="t('studio.newApp')" form @submit="create"><AlertBanner :message="createError" tone="error" /><div class="grid grid-cols-2 gap-2"><ActionCard class="relative p-3 pr-10" :active="form.app_type === 'workflow'" :aria-pressed="form.app_type === 'workflow'" @click="selectAppType('workflow')"><WorkflowIcon :size="18" /><div class="mt-2 text-sm font-medium">{{ t('studio.workflow') }}</div><span v-if="form.app_type === 'workflow'" aria-hidden="true" class="absolute right-2 top-2 flex h-5 w-5 items-center justify-center rounded-full bg-[var(--primary)] text-white"><Check :size="12" :stroke-width="3" /></span></ActionCard><ActionCard class="relative p-3 pr-10" :active="form.app_type === 'chat'" :aria-pressed="form.app_type === 'chat'" @click="selectAppType('chat')"><Bot :size="18" /><div class="mt-2 text-sm font-medium">{{ t('studio.chat') }}</div><span v-if="form.app_type === 'chat'" aria-hidden="true" class="absolute right-2 top-2 flex h-5 w-5 items-center justify-center rounded-full bg-[var(--primary)] text-white"><Check :size="12" :stroke-width="3" /></span></ActionCard></div><FormField class="mt-4" :label="t('common.name')" required><InputText v-model="form.name" required /></FormField><FormField class="mt-4" :label="t('common.description')"><Textarea v-model="form.description" class="h-20" /></FormField><template #footer><Button type="button" variant="secondary" @click="showCreate = false">{{ t('common.cancel') }}</Button><Button type="submit" :loading="creating">{{ t('common.create') }}</Button></template></ModalShell></div>
<ModalShell :model-value="Boolean(pendingDelete)" :title="t('studio.deleteTitle')" @update:model-value="closeDelete"><AlertBanner :message="deleteError" tone="error" /><div class="flex items-start gap-3 rounded-lg bg-red-50 p-4 text-sm text-red-700 dark:bg-red-950/30 dark:text-red-300"><CircleAlert class="mt-0.5 shrink-0" :size="18" /><div><p class="font-semibold">{{ t('studio.confirmDelete', { name: pendingDelete?.name || '' }) }}</p><p class="mt-1 text-xs leading-5">{{ t('studio.deleteWarning') }}</p></div></div><template #footer><Button type="button" variant="secondary" :disabled="deleting" @click="closeDelete">{{ t('common.cancel') }}</Button><Button type="button" variant="danger" :loading="deleting" @click="confirmDelete"><Trash2 :size="15" />{{ t('common.delete') }}</Button></template></ModalShell></AppShell></template>
